using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text.Json;using FluentAssertions;
namespace VetCommission.IntegrationTests.WebApi;
[Collection(WebApiCollection.Name)]public sealed class ProcedureEndpointTests(WebApiTestFactory factory){const string Tenant="11111111-1111-1111-1111-111111111111";const string Clinic="77777777-7777-7777-7777-777777777771";[Fact]public async Task Procedure_CanCreateReadUpdateAndDeactivate(){using var c=await Client();var cat=await c.PostAsJsonAsync("/api/categorias-procedimentos",new{name="Categoria procedimento",description="Teste"});cat.EnsureSuccessStatusCode();using var cj=JsonDocument.Parse(await cat.Content.ReadAsStringAsync());var categoryId=cj.RootElement.GetProperty("id").GetGuid();var create=await c.PostAsJsonAsync("/api/procedimentos",new{categoryId,code="P-001",name="Consulta",description="Consulta inicial",defaultValue=150m});create.StatusCode.Should().Be(HttpStatusCode.OK);using var pj=JsonDocument.Parse(await create.Content.ReadAsStringAsync());var id=pj.RootElement.GetProperty("id").GetGuid();var get=await c.GetAsync($"/api/procedimentos/{id}");get.StatusCode.Should().Be(HttpStatusCode.OK);var update=await c.PutAsJsonAsync($"/api/procedimentos/{id}",new{categoryId,code="P-001",name="Consulta atualizada",description="Alterada",defaultValue=175m});update.StatusCode.Should().Be(HttpStatusCode.OK);var off=await c.PostAsync($"/api/procedimentos/{id}/inativar",null);off.StatusCode.Should().Be(HttpStatusCode.OK);}async Task<HttpClient>Client(){var c=factory.CreateClient();var login=await c.PostAsJsonAsync("/api/auth/login",new{email="admin@vetcommission.local",senha="qwas"});login.EnsureSuccessStatusCode();using var p=JsonDocument.Parse(await login.Content.ReadAsStringAsync());c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",p.RootElement.GetProperty("accessToken").GetString());c.DefaultRequestHeaders.Add("X-Tenant-Id",Tenant);c.DefaultRequestHeaders.Add("X-Clinic-Id",Clinic);return c;}}
